export async function loadNodeFullById(nodeId: string): Promise<NodeFull | undefined> {
  const summary = mdxNodeSummariesById[nodeId]
  if (!summary) return undefined
  const loader = nodeLoaderById[nodeId]
  if (!loader) return undefined
  const mod = await loader()
  const moduleMeta = (mod.meta || {}) as Partial<NodeSummary>
  return {
    ...summary,
    ...moduleMeta,
    content: { type: 'mdx', Component: mod.default },
  }
}
